import random
from collections import deque
W,H=60,40

def gen(seed, fill):
    rng=random.Random(seed)
    g=[[1 if rng.random()<fill else 0 for _ in range(W)] for _ in range(H)]
    def nb(y,x):
        n=0
        for dy in(-1,0,1):
            for dx in(-1,0,1):
                if dy==dx==0: continue
                yy,xx=y+dy,x+dx
                if not(0<=yy<H and 0<=xx<W) or g[yy][xx]==1: n+=1
        return n
    for _ in range(5):
        ng=[[0]*W for _ in range(H)]
        for y in range(H):
            for x in range(W):
                ng[y][x]=1 if nb(y,x)>=5 else 0
        g=ng
    seen=set(); best=set()
    for y in range(H):
        for x in range(W):
            if g[y][x]==0 and (y,x) not in seen:
                reg=set(); q=deque([(y,x)]); seen.add((y,x))
                while q:
                    cy,cx=q.popleft(); reg.add((cy,cx))
                    for ny,nx in((cy-1,cx),(cy+1,cx),(cy,cx-1),(cy,cx+1)):
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==0 and (ny,nx) not in seen:
