                if len(reg)>len(best): best=reg
    grid=[[0 if (y,x) in best else 1 for x in range(W)] for y in range(H)]
    for x in range(W): grid[0][x]=grid[H-1][x]=1
    for y in range(H): grid[y][0]=grid[y][W-1]=1
    return grid

